import{_ as t,o as h,c as i,a2 as c}from"./chunks/framework.mRCPFc5l.js";const l=JSON.parse('{"title":"Nghệ thuật · Thiết kế","description":"","frontmatter":{},"headers":[],"relativePath":"ideas/inquiry-ib/nghe-thuat-thiet-ke.md","filePath":"ideas/inquiry-ib/nghe-thuat-thiet-ke.md"}'),g={name:"ideas/inquiry-ib/nghe-thuat-thiet-ke.md"};function a(o,n,e,m,r,u){return h(),i("div",null,[...n[0]||(n[0]=[c('<h1 id="nghe-thuat-·-thiet-ke" tabindex="-1">Nghệ thuật · Thiết kế <a class="header-anchor" href="#nghe-thuat-·-thiet-ke" aria-label="Permalink to &quot;Nghệ thuật · Thiết kế&quot;">​</a></h1><p>Trên trang này# Nghệ thuật · Thiết kế — ba bài học inquiry theo IB <a href="#nghe-thuat-·-thiet-ke-—-ba-bai-hoc-inquiry-theo-ib">​</a> Đây là hai nhóm môn riêng trong IB — <strong>Arts</strong> và <strong>Design</strong> — nhưng chúng chia sẻ một cấu trúc: học sinh <strong>điều tra trước, làm sau, và đánh giá lại cuối cùng</strong>. Sản phẩm cuối chỉ là một trong bốn tiêu chí chấm; quá trình chiếm phần lớn. Đây cũng là chỗ khác biệt rõ nhất với cách dạy Mỹ thuật hoặc Công nghệ quen thuộc, nơi thường chỉ sản phẩm cuối được nhìn tới. Ý xuyên suốt cả mônTác phẩm hay sản phẩm tốt không đến từ cảm hứng. Nó đến từ những lựa chọn cụ thể tạo ra hiệu ứng cụ thể — và các lựa chọn đó phân tích được, học được. Cũng quan trọng — nhưng không phải ý lớn nhất- Giải pháp bắt đầu từ nhu cầu có thật của một người thật, không từ ý tưởng của người thiết kế.</p><ul><li>Quá trình được chấm ngang với sản phẩm, nên đánh giá trung thực về chỗ chưa đạt cũng được tính điểm.</li><li>Người xem và người nghe bị dẫn dắt bởi chính những thứ họ không nhận ra là đang dẫn dắt mình.</li></ul><h2 id="demo-1-—-design-giai-mot-van-đe-cua-nguoi-that-​" tabindex="-1">Demo 1 — Design: giải một vấn đề của người thật <a href="#demo-1-—-design-giai-mot-van-đe-cua-nguoi-that">​</a> <a class="header-anchor" href="#demo-1-—-design-giai-mot-van-đe-cua-nguoi-that-​" aria-label="Permalink to &quot;Demo 1 — Design: giải một vấn đề của người thật [​](#demo-1-—-design-giai-mot-van-đe-cua-nguoi-that)&quot;">​</a></h2><p><strong>Lớp</strong>8–11<strong>Key concept</strong>Development<strong>Related concepts</strong>Function · Evaluation · Markets and trends<strong>Global context</strong>Identities and relationships<strong>Statement of inquiry</strong>Một giải pháp tốt bắt đầu từ việc hiểu nhu cầu thật của người dùng, không từ ý tưởng của người thiết kế.<strong>Cần biết trước</strong>Không cần kiến thức chuyên môn — đây là bài mở đầu</p><h3 id="chu-trinh-thiet-ke-cua-ib-​" tabindex="-1">Chu trình thiết kế của IB <a href="#chu-trinh-thiet-ke-cua-ib">​</a> <a class="header-anchor" href="#chu-trinh-thiet-ke-cua-ib-​" aria-label="Permalink to &quot;Chu trình thiết kế của IB [​](#chu-trinh-thiet-ke-cua-ib)&quot;">​</a></h3><p>textA. Inquiring &amp; analysing → B. Developing ideas ↑ ↓ D. Evaluating ← C. Creating the solutionBốn giai đoạn, và <strong>cả bốn đều được chấm điểm ngang nhau</strong>. Một học sinh làm ra sản phẩm đẹp nhưng bỏ qua giai đoạn A vẫn không đạt điểm cao — vì em ấy đã giải một vấn đề tự nghĩ ra thay vì một vấn đề có thật.</p><h3 id="dien-bien-du-an-4–6-tuan-​" tabindex="-1">Diễn biến dự án (4–6 tuần) <a href="#dien-bien-du-an-4–6-tuan">​</a> <a class="header-anchor" href="#dien-bien-du-an-4–6-tuan-​" aria-label="Permalink to &quot;Diễn biến dự án (4–6 tuần) [​](#dien-bien-du-an-4–6-tuan)&quot;">​</a></h3><p><strong>Giai đoạn A — Điều tra (1,5 tuần).</strong> Đề bài rất mở: <em>&quot;Tìm một người trong trường đang gặp một khó khăn hằng ngày. Thiết kế thứ gì đó giúp họ.&quot;</em> Học sinh <strong>bắt buộc phỏng vấn người dùng thật</strong> — bác bảo vệ, cô lao công, một bạn khuyết tật, thủ thư, một em lớp dưới. Giáo viên kiểm tra một điều duy nhất trước khi cho sang giai đoạn B: <em>&quot;Vấn đề này do em nghĩ ra, hay do người đó nói ra?&quot;</em> Đây là bộ lọc quan trọng nhất của cả dự án. Học sinh rất hay nhảy thẳng vào ý tưởng mình thích rồi đi tìm người để áp vào. Sản phẩm giai đoạn này: bản ghi phỏng vấn, phân tích các giải pháp đã có trên thị trường (chúng thiếu gì?), và một <strong>bản đặc tả thiết kế</strong> — danh sách tiêu chí mà giải pháp phải đạt, viết ra <strong>trước khi</strong> có ý tưởng nào. <strong>Giai đoạn B — Phát triển ý tưởng (1,5 tuần).</strong> Bắt buộc phác thảo <strong>ít nhất ba phương án khác nhau</strong>, không phải ba phiên bản của cùng một ý. Mỗi phương án được chấm lại theo bản đặc tả ở giai đoạn A. <em>&quot;Phương án 2 đạt 4/6 tiêu chí. Phương án 3 đạt 5/6 nhưng đắt gấp đôi. Em chọn cái nào và vì sao?&quot;</em> Quyết định phải được viết ra và bảo vệ. Đây là chỗ dự án dạy tư duy đánh đổi. <strong>Giai đoạn C — Làm ra (2 tuần).</strong> Học sinh ghi nhật ký: gặp vấn đề gì, sửa thế nào, đổi kế hoạch ở đâu. Nhật ký được chấm — vì việc kế hoạch phải thay đổi là điều bình thường, và cách xử lý thay đổi mới là kỹ năng thật. <strong>Giai đoạn D — Đánh giá (1 tuần).</strong> Đưa sản phẩm cho <strong>chính người dùng ban đầu</strong> thử. Ghi lại phản hồi thật, kể cả phản hồi tiêu cực. Câu hỏi cuối cùng, và là câu chiếm nhiều điểm nhất: <em>&quot;Giải pháp của em đạt được bao nhiêu tiêu chí trong bản đặc tả? Chỗ nào không đạt? Nếu làm lại, em đổi gì?&quot;</em> Một học sinh trung thực nói <em>&quot;sản phẩm của em nặng quá, bác bảo vệ dùng được nhưng không thoải mái, lần sau em sẽ dùng vật liệu khác&quot;</em> <strong>được điểm cao hơn</strong> một học sinh nói sản phẩm hoàn hảo. Đây là điều đáng chú ý nhất về cách chấm của IB ở môn này: <strong>sự trung thực trong đánh giá được tính điểm</strong>.</p><h2 id="demo-2-—-my-thuat-bo-cuc-dan-mat-nguoi-xem-​" tabindex="-1">Demo 2 — Mỹ thuật: bố cục dẫn mắt người xem <a href="#demo-2-—-my-thuat-bo-cuc-dan-mat-nguoi-xem">​</a> <a class="header-anchor" href="#demo-2-—-my-thuat-bo-cuc-dan-mat-nguoi-xem-​" aria-label="Permalink to &quot;Demo 2 — Mỹ thuật: bố cục dẫn mắt người xem [​](#demo-2-—-my-thuat-bo-cuc-dan-mat-nguoi-xem)&quot;">​</a></h2><p><strong>Lớp</strong>8–10<strong>Key concept</strong>Aesthetics<strong>Related concepts</strong>Composition · Visual culture · Interpretation<strong>Global context</strong>Personal and cultural expression<strong>Statement of inquiry</strong>Người sáng tạo điều khiển sự chú ý của người xem bằng những lựa chọn mà người xem không nhận ra.<strong>Cần biết trước</strong>Không cần</p><h3 id="dien-bien-tiet-hoc-​" tabindex="-1">Diễn biến tiết học <a href="#dien-bien-tiet-hoc">​</a> <a class="header-anchor" href="#dien-bien-tiet-hoc-​" aria-label="Permalink to &quot;Diễn biến tiết học [​](#dien-bien-tiet-hoc)&quot;">​</a></h3><p><strong>Bước 1 — Theo dõi ánh mắt của chính mình (10 phút).</strong> Giáo viên chiếu một bức tranh trong 5 giây rồi tắt. <em>&quot;Em nhìn vào đâu đầu tiên? Vẽ nhanh sơ đồ đường mắt em đã đi.&quot;</em> So sánh giữa các học sinh: đường đi của mắt <strong>giống nhau đến bất ngờ</strong>. <em>&quot;Vì sao chúng ta lại nhìn giống nhau? Có ai bảo chúng ta nhìn vào đó đâu?&quot;</em><strong>Bước 2 — Truy tìm cơ chế (15 phút).</strong> Học sinh phân tích: chỗ nào sáng nhất, chỗ nào tương phản mạnh nhất, các đường trong tranh dẫn về đâu, mặt người nhìn về hướng nào. Giáo viên chỉ hỏi, không giảng: <em>&quot;Nếu bỏ vệt sáng đó đi thì sao? Nếu nhân vật nhìn hướng khác thì mắt em còn đi theo không?&quot;</em><strong>Bước 3 — Thử nghiệm trực tiếp (20 phút).</strong> Học sinh dựng ba bố cục cùng một chủ đề bằng cách cắt dán hoặc phần mềm, mỗi bố cục cố tình đưa mắt người xem tới một điểm khác nhau. Rồi thử trên bạn cùng lớp: <em>&quot;Nhìn 3 giây. Em thấy cái gì đầu tiên?&quot;</em> Học sinh có ngay dữ liệu về việc bố cục của mình có hiệu quả không — một vòng phản hồi mà môn Mỹ thuật hiếm khi có. <strong>Bước 4 — Mở rộng ra đời sống (10 phút).</strong> Phân tích một trang quảng cáo, một giao diện ứng dụng, một trang báo. <em>&quot;Người thiết kế muốn em nhìn vào đâu trước? Họ làm điều đó bằng cách nào? Họ muốn em bấm vào cái gì?&quot;</em> Đây là chỗ môn Mỹ thuật trở thành kỹ năng đọc thế giới hình ảnh — thứ mà một đứa trẻ dùng hàng chục lần mỗi ngày.</p><h2 id="demo-3-—-am-nhac-am-thanh-tao-cam-xuc-bang-cach-nao-​" tabindex="-1">Demo 3 — Âm nhạc: âm thanh tạo cảm xúc bằng cách nào <a href="#demo-3-—-am-nhac-am-thanh-tao-cam-xuc-bang-cach-nao">​</a> <a class="header-anchor" href="#demo-3-—-am-nhac-am-thanh-tao-cam-xuc-bang-cach-nao-​" aria-label="Permalink to &quot;Demo 3 — Âm nhạc: âm thanh tạo cảm xúc bằng cách nào [​](#demo-3-—-am-nhac-am-thanh-tao-cam-xuc-bang-cach-nao)&quot;">​</a></h2><p><strong>Lớp</strong>8–11<strong>Key concept</strong>Communication<strong>Related concepts</strong>Expression · Structure · Audience<strong>Global context</strong>Personal and cultural expression<strong>Statement of inquiry</strong>Cảm xúc được gợi lên bằng những lựa chọn kỹ thuật cụ thể, phân tích và tái tạo được.<strong>Cần biết trước</strong>Không cần biết nhạc lý — bài này xây từ nghe</p><h3 id="dien-bien-tiet-hoc-​-1" tabindex="-1">Diễn biến tiết học <a href="#dien-bien-tiet-hoc-1">​</a> <a class="header-anchor" href="#dien-bien-tiet-hoc-​-1" aria-label="Permalink to &quot;Diễn biến tiết học [​](#dien-bien-tiet-hoc-1)&quot;">​</a></h3><p><strong>Bước 1 — Nghe mù (12 phút).</strong> Giáo viên mở ba đoạn nhạc không lời, mỗi đoạn 40 giây. <em>&quot;Với mỗi đoạn, viết ba tính từ. Đừng nghĩ nhiều.&quot;</em> So sánh: cả lớp dùng những từ rất giống nhau cho cùng một đoạn. <em>&quot;Vì sao 30 người lại cảm thấy giống nhau? Nhạc sĩ đã làm gì?&quot;</em><strong>Bước 2 — Tách biến (18 phút).</strong> Giáo viên mở lại từng đoạn, mỗi lần chỉ chú ý một yếu tố: nhịp độ · độ cao · âm sắc nhạc cụ · sáng-tối của hoà âm · mật độ âm thanh. Lớp lập bảng đối chiếu ba đoạn theo năm yếu tố. Quy luật hiện ra khá rõ. <strong>Bước 3 — Thử nghiệm (20 phút).</strong> Học sinh dùng một phần mềm làm nhạc đơn giản, lấy <strong>cùng một giai điệu</strong> và tạo ba phiên bản: một vui, một buồn, một căng thẳng. Ràng buộc: <strong>không được đổi nốt nhạc</strong>. Chỉ được đổi nhịp độ, nhạc cụ, và hoà âm nền. Ràng buộc này khiến học sinh phải dùng đúng những yếu tố vừa phân tích, thay vì viết lại một giai điệu khác. <strong>Bước 4 — Kiểm chứng (10 phút).</strong> Cho lớp nghe mù ba phiên bản và đoán cảm xúc. Nếu bạn đoán đúng — thiết kế âm thanh đã hiệu quả. <strong>Bước 5 — Nối ra đời sống (8 phút).</strong> Xem một cảnh phim hai lần: một lần có nhạc gốc, một lần tắt tiếng nhạc. <em>&quot;Cảnh nào đáng sợ hơn? Nhưng hình ảnh có đổi gì đâu?&quot;</em> Điều đáng chú ý ở cả ba demo Trong cả Nghệ thuật lẫn Thiết kế, IB chấm <strong>quá trình ngang với sản phẩm</strong>. Một học sinh không có năng khiếu vẽ vẫn đạt điểm cao nếu điều tra kỹ, thử nhiều phương án, và đánh giá trung thực. Điều này mở cửa môn học cho những đứa trẻ vốn tin rằng &quot;con không có khiếu&quot; — và đó là một trong những đóng góp lặng lẽ nhất của khung IB. <a href="/ideas/inquiry-ib/">Quay lại: tổng quan demo IB →</a></p>',17)])])}const b=t(g,[["render",a]]);export{l as __pageData,b as default};
